(r, big) => {
  const n = big ? 100 : r.int(1, 3), total = big ? 50000 : r.int(1, 6);
  const logs = [], stack = [];
  let t = 0, lastEnd = false, calls = 0;
  const step = () => { t += big ? r.int(0, 20000) : r.int(0, 2); };
  while (calls < total || stack.length) {
    if (calls < total && (stack.length === 0 || r.bool(0.5))) {
      step(); if (lastEnd) t = Math.max(t, logs.length ? +logs[logs.length - 1].split(":")[2] + 1 : 0);
      const id = r.int(0, n - 1); stack.push(id); calls++;
      logs.push(id + ":start:" + t); lastEnd = false;
    } else {
      step();
      logs.push(stack.pop() + ":end:" + t); lastEnd = true;
    }
  }
  return [n, logs];
}

