function selfTimes(n: number, logs: string[]): number[] {
  const ev = logs.map(l => { const [id, type, t] = l.split(":"); return { id: +id, start: type === "start", t: +t }; });
  const res = new Array(n).fill(0), stack: number[] = [];
  let k = 0;
  const last = ev[ev.length - 1].t;
  for (let u = 0; u <= last; u++) {
    while (k < ev.length && ev[k].t === u && ev[k].start) stack.push(ev[k++].id);
    if (stack.length) res[stack[stack.length - 1]]++;
    while (k < ev.length && ev[k].t === u && !ev[k].start) { stack.pop(); k++; }
  }
  return res;
}

