    def selfTimes(self, n: int, logs: List[str]) -> List[int]:
        ev = []
        for line in logs:
            fid, kind, t = line.split(":")
            ev.append((int(fid), kind == "start", int(t)))
        res, stack, k = [0] * n, [], 0
        for u in range(ev[-1][2] + 1):
            while k < len(ev) and ev[k][2] == u and ev[k][1]:
                stack.append(ev[k][0])
                k += 1
            if stack:
                res[stack[-1]] += 1
            while k < len(ev) and ev[k][2] == u and not ev[k][1]:
                stack.pop()
                k += 1
        return res

