function selfTimes(n: number, logs: string[]): number[] {
  const res = new Array(n).fill(0), stack: number[] = [];
  let prev = 0;
  for (const line of logs) {
    const [idStr, type, tStr] = line.split(":");
    const id = +idStr, t = +tStr;
    if (type === "start") {
      if (stack.length) res[stack[stack.length - 1]] += t - prev;
      stack.push(id);
      prev = t;
    } else {
      res[stack.pop()!] += t - prev + 1;
      prev = t + 1; // unit t is used up
    }
  }
  return res;
}

